// CSD_RATIONALE_BEGIN
// Previous attempt timed out because the Dafny verifier had to process
// many nested while-loops with complex interleaved decreases clauses and
// multiple simultaneous invariants, blowing the 30-second budget.
//
// Fix: eliminate every loop. Replace the entire multi-phase loop structure
// with three sequential if-branches:
//   Phase 1 – UnconstrainedChunk (free reasoning, self-stops on "<<")
//   Phase 2 – OpenConstrainedSpan (1 step, forced if still outside after Phase 1)
//   Phase 3 – CloseSpanWithinBudget (uses all remaining budget)
//
// With no loops, Dafny verifies only three straight-line code paths against
// helper postconditions and simple linear arithmetic – well within 30 s.
//
// For gsm_symbolic / Qwen3.5-2B the guidance string tells the model to emit
// "<<EXPR>>" naturally, so Phase 1 typically catches the span opening and
// leaves 150+ steps for Phase 3 to generate and close the expression.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// There are no loops, so "loop invariants" become sequential-composition
// invariants maintained after each phase.
//
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedChunk + EnterObservedConstrainedSpan):
//     When soo1 is true the helper postcondition sets currentConstrainedOut:=[];
//     parser.IsValidPrefix([]) holds by the method precondition. ✓
//
//   Phase 2 (OpenConstrainedSpan):
//     Postcondition sets currentConstrainedOut:=[];
//     same parser.IsValidPrefix([]) argument. ✓
//
//   Phase 3 (CloseSpanWithinBudget):
//     Library postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut)
//     directly, covering both the closed and still-open outcomes. ✓
//
// Invariant 2 – progress: |generated| <= |generatedPrefix| + cost
//
//   Phase 1: UnconstrainedChunk postcondition:
//     |generatedOut| <= |generated_old| + su1; cost grows by su1. ✓
//     EnterObservedConstrainedSpan appends nothing. ✓
//
//   Phase 2: OpenConstrainedSpan appends exactly one "<<" token;
//     cost grows by 1 in lockstep, preserving the bound. ✓
//
//   Phase 3: CloseSpanWithinBudget postcondition:
//     |generatedOut| <= |generated_before_ph3| + bud3.
//     |generated_before_ph3| <= |generatedPrefix| + cost_before_ph3,
//     so |generated_final| <= |generatedPrefix| + cost_before_ph3 + bud3
//       = |generatedPrefix| + cost_before_ph3 + (maxSteps - cost_before_ph3)
//       = |generatedPrefix| + maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  return;
}

helpers.AppendTaskGuidance(lm,
  "Think step by step. End your answer with: The answer is <<EXPR>> (using << and >> as delimiters) where EXPR is a concise numeric expression using the variable names from the problem and standard arithmetic (+, -, *, /, parentheses). Do not include curly braces in EXPR.");

// Reserve 150 steps for constrained-span generation; use the rest for free reasoning
var constrainedReserve: nat := 150;
var freeBudget: nat;
if maxSteps > constrainedReserve {
  freeBudget := maxSteps - constrainedReserve;
} else {
  freeBudget := 0;
}

// Phase 1: Free generation; self-stops when the model naturally emits "<<"
if !insideConstrainedOut && freeBudget > 0 {
  var cg1, soo1, soe1, su1 :=
    helpers.UnconstrainedChunk(lm, prompt, generated, freeBudget, "<<", eosToken);
  generated := cg1;
  cost := cost + su1;
  if soo1 {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2: Force open a constrained span if model did not emit "<<" on its own
if !insideConstrainedOut && cost < maxSteps {
  var og2, oi2, oc2 := helpers.OpenConstrainedSpan(lm, generated);
  generated := og2;
  insideConstrainedOut := oi2;
  currentConstrainedOut := oc2;
  cost := cost + 1;
}

// Phase 3: Generate and close the constrained expression within remaining budget
if insideConstrainedOut && cost < maxSteps {
  var bud3 := maxSteps - cost;
  var wg3, wi3, wc3 :=
    helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud3);
  generated := wg3;
  insideConstrainedOut := wi3;
  currentConstrainedOut := wc3;
  cost := cost + bud3;
}

